:root {
  --bg: #0e0f12;
  --surface: #15171c;
  --surface-2: #1c1f26;
  --border: #262a33;
  --text: #f2f0ea;
  --muted: #8b8f99;
  --accent: #c6ff3d;
  --accent-dim: #a6d62e;
  --radius: 2px;
  --font-head: 'Helvetica Neue', 'Arial Black', 'Impact', sans-serif;
  --font-body: 'Helvetica Neue', Arial, sans-serif;
  --max-w: 1200px;
  --gap: clamp(24px, 4vw, 64px);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -60px;
  z-index: 200;
  background: var(--accent);
  color: var(--bg);
  padding: 10px 18px;
  font-size: 0.85rem;
  font-weight: 700;
  border-radius: var(--radius);
  transition: top 0.2s ease;
}

.skip-link:focus {
  top: 12px;
}

.site {
  min-height: 100vh;
  overflow-x: hidden;
}

main > section {
  padding: clamp(64px, 9vw, 120px) 0;
  border-bottom: 1px solid var(--border);
}

.container {
  width: 100%;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gap);
}

[data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  [data-reveal] { opacity: 1; transform: none; transition: none; }
  .btn { transition: none; }
}

.nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  background: rgba(14,15,18,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gap);
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.nav-logo {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 1.12rem;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--text);
  padding: 8px 0;
}

.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.4vw, 34px);
}

.nav-link {
  position: relative;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  padding: 8px 0;
  transition: color 0.2s ease;
}

.nav-link::after {
  content: '';
  position: absolute;
  left: 0; bottom: 0;
  width: 100%;
  height: 2px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}

.nav-link:hover,
.nav-link:focus-visible { color: var(--text); }

.nav-link.active { color: var(--accent); }

.nav-link.active::after { transform: scaleX(1); }

.nav-toggle {
  display: none;
  width: 44px; height: 44px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: transparent;
}

.nav-toggle:hover { border-color: var(--accent); }

.nav-toggle span {
  display: block;
  width: 20px; height: 2px;
  background: var(--text);
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-menu { display: none; }

@media (max-width: 820px) {
  .nav-links { display: none; }
  .nav-toggle { display: flex; }

  .mobile-menu {
    display: block;
    position: fixed;
    inset: 72px 0 0 0;
    background: var(--bg);
    z-index: 99;
    padding: 32px var(--gap);
    overflow-y: auto;
  }

  .mobile-links {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .mobile-link {
    display: block;
    width: 100%;
    text-align: left;
    font-family: var(--font-head);
    font-size: 1.6rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    padding: 16px 0;
    border-bottom: 1px solid var(--border);
    color: var(--text);
    transition: color 0.2s ease, padding-left 0.2s ease;
  }

  .mobile-link:hover,
  .mobile-link:focus-visible {
    color: var(--accent);
    padding-left: 8px;
  }

  .mobile-link.active { color: var(--accent); }
}

.hero {
  position: relative;
  padding-top: 72px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: var(--gap);
  align-items: center;
  width: 100%;
}

.hero-copy {
  display: flex;
  flex-direction: column;
  gap: 26px;
  padding: 72px 0;
}

.hero-eyebrow {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
}

.hero-title {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(3.2rem, 8.5vw, 7rem);
  line-height: 0.94;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  color: var(--text);
}

.hero-title em {
  font-style: normal;
  color: var(--accent);
  display: block;
}

.hero-sub {
  max-width: 44ch;
  font-size: clamp(1rem, 1.4vw, 1.15rem);
  color: var(--muted);
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  margin-top: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 32px;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: var(--radius);
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease, transform 0.15s ease;
}

.btn-primary {
  background: var(--accent);
  color: #0e0f12;
  border: 2px solid var(--accent);
}

.btn-primary:hover,
.btn-primary:focus-visible {
  background: transparent;
  color: var(--accent);
}

.btn-primary:active { transform: translateY(1px); }

.btn-ghost {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--border);
}

.btn-ghost:hover,
.btn-ghost:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
}

.btn-ghost:active { transform: translateY(1px); }

.hero-visual {
  position: relative;
  aspect-ratio: 1 / 1;
  max-width: 480px;
  justify-self: end;
  width: 100%;
}

.geo {
  position: absolute;
  border-radius: var(--radius);
}

.geo-1 {
  top: 0; right: 0;
  width: 70%; height: 70%;
  background: var(--accent);
}

.geo-2 {
  bottom: 0; left: 0;
  width: 60%; height: 60%;
  background: var(--surface-2);
  border: 1px solid var(--border);
}

.geo-3 {
  top: 12%; left: 6%;
  width: 34%; height: 34%;
  border: 2px solid var(--text);
  border-radius: 50%;
  background: transparent;
}

.geo-4 {
  bottom: 18%; right: 8%;
  width: 26%; height: 26%;
  background: var(--accent-dim);
  transform: rotate(45deg);
}

.geo-label {
  position: absolute;
  bottom: 0; right: 0;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  writing-mode: vertical-rl;
}

@media (max-width: 820px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-copy { padding: 56px 0 32px; }
  .hero-visual {
    justify-self: start;
    max-width: 320px;
    aspect-ratio: 4 / 3;
    margin-bottom: 48px;
