  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.service-name {
  font-family: var(--font-head);
  font-weight: 800;
  font-size: clamp(1.2rem, 1.8vw, 1.5rem);
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--text);
}

.service-desc {
  color: var(--muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

